import{_ as n,a0 as a,w as l,s as r,ao as p,I as t,x as o,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"看漫畫學 SELinux 強制策略 | LCTT x X-CMD","titleTemplate":false,"description":"看漫畫學 SELinux 強制策略 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"看漫畫學 SELinux 強制策略 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"看漫畫學 SELinux 強制策略 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20131113 Your visual how-to guide for SELinux policy enforcement","title":"看漫畫學 SELinux 強制策略","tag":"201703","desc":""},"relativePath":"201703/20131113 Your visual how-to guide for SELinux policy enforcement.md","filePath":"[post].md"}'),c={name:"201703/20131113 Your visual how-to guide for SELinux policy enforcement.md"};function u(m,e,f,g,h,_){const d=a("Link");return l(),r("div",null,[e[23]||(e[23]=p('<h1 id="看漫畫學-selinux-強制策略" tabindex="-1">看漫畫學 SELinux 強制策略 <a class="header-anchor" href="#看漫畫學-selinux-強制策略" aria-label="Permalink to “看漫畫學 SELinux 強制策略”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life-uploads/selinux_rules_lead_image.png?itok=jxV7NgtD" alt="SELinux policy guide" title="Your visual how-to guide for SELinux policy enforcement"></p><blockquote><p>圖像來自:  opensource.com</p></blockquote><p>今年是我們一起慶祝 SELinux 紀念日的第十個年頭了（LCTT 譯者注：本文發表於 2013 年）。真是太難以置信了！SELinux 最初在 Fedora Core 3 中被引入，隨後加入了紅帽企業版 Linux 4。從來沒有使用過 SELinux 的傢伙，你可要好好兒找個理由了……</p><p>SElinux 是一個標籤型系統。每一個進程都有一個標籤。操作系統中的每一個文件/目錄客體（object）也都有一個標籤。甚至連網絡端口、設備，乃至潛在的主機名都被分配了標籤。我們把控制訪問進程的標籤的規則寫入一個類似文件的客體標籤中，這些規則我們稱之為策略（policy）。內核強制實施了這些規則。有時候這種“強制”被稱為強制訪問控制體系（Mandatory Access Control）（MAC）。</p><p>一個客體的擁有者對客體的安全屬性並沒有自主權。標準 Linux 訪問控制體系，擁有者/分組 + 權限標誌如 rwx，常常被稱作自主訪問控制（Discretionary Access Control）（DAC）。SELinux 沒有文件 UID 或擁有權的概念。一切都被標籤控制，這意味着在沒有至高無上的 root 權限進程時，也可以設置 SELinux 系統。</p><p><strong>注意：</strong> _SELinux不允許你摒棄 DAC 控制。SELinux 是一個並行的強制模型。一個應用必須同時支持 SELinux 和 DAC 來完成特定的行為。這可能會導致管理員迷惑為什麼進程被拒絕訪問。管理員被拒絕訪問是因為在 DAC 中有些問題，而不是在 SELinux 標籤。</p><h3 id="類型強制" tabindex="-1">類型強制 <a class="header-anchor" href="#類型強制" aria-label="Permalink to “類型強制”">​</a></h3><p>讓我們更深入的研究下標籤。SELinux 最主要的“模型”或“強制”叫做類型強制（type enforcement）。基本上這意味着我們根據進程的類型來定義其標籤，以及根據文件系統客體的類型來定義其標籤。</p><p><em>打個比方</em></p><p>想像一下在一個系統裏定義客體的類型為貓和狗。貓（CAT）和狗（DOG）都是進程類型（process type）。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/type-enforcement_01_catdog.png" alt="Image showing a cartoon of a cat and dog."></p><p>我們有一類希望能與之交互的客體，我們稱之為食物。而我希望能夠為食物增加類型：<code>cat_food</code> （貓的食物）和 <code>dog_food</code>（狗的食物）。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/type-enforcement_03_foods.png" alt="Cartoon Cat eating Cat Food and Dog eating Dog Food"></p><p>作為一個策略制定者，我可以説一隻狗有權限去吃狗糧（<code>dog_chow</code>），而一隻貓有權限去吃貓糧（<code>cat_chow</code>）。在 SELinux 中我可以將這條規則寫入策略中。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/type-enforcement_04_policy.png" alt="allow cat cat_chow:food eat; allow dog dog_chow:food eat" title="SELinux rule"></p><p><code>allow cat cat_chow:food eat;</code></p><p><code>允許 貓 貓糧：食物 吃；</code></p><p><code>allow dog dog_chow:food eat;</code></p><p><code>允許 狗 狗糧：食物 吃；</code></p><p>有了這些規則，內核會允許貓進程去吃打上貓糧標籤 <code>cat_chow</code> 的食物，允許狗去吃打上狗糧標籤 <code>dog_chow</code> 的食物。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/type-enforcement_02_eat.png" alt="Cartoon Cat eating Cat Food and Dog eating Dog Food"></p><p>此外，在 SELinux 系統中，由於禁止是默認規則，這意味着，如果狗進程想要去吃貓糧 <code>cat_chow</code>，內核會阻止它。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/type-enforcement_06_tux-dog-leash.png" alt=""></p><p>同理，貓也不允許去接觸狗糧。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_07_tux-cat-no.png" alt="Cartoon cat not allowed to eat dog fooda" title="Cartoon cat not allowed to eat dog fooda"></p><p><em>現實例子</em></p><p>我們將 Apache 進程標為 <code>httpd_t</code>，將 Apache 上下文標為 <code>httpd_sys_content_t</code> 和 <code>httpdsys_content_rw_t</code>。假設我們把信用卡數據存儲在 MySQL 資料庫中，其標籤為 <code>msyqld_data_t</code>。如果一個 Apache 進程被劫持，黑客可以獲得 <code>httpd_t</code> 進程的控制權，從而能夠去讀取 <code>httpd_sys_content_t</code> 文件並向 <code>httpd_sys_content_rw_t</code> 文件執行寫操作。但是黑客卻不允許去讀信用卡數據（<code>mysqld_data_t</code>），即使 Apache 進程是在 root 下運行。在這種情況下 SELinux 減輕了這次闖入的後果。</p><h3 id="多類別安全強制" tabindex="-1">多類別安全強制 <a class="header-anchor" href="#多類別安全強制" aria-label="Permalink to “多類別安全強制”">​</a></h3><p><em>打個比方</em></p><p>上面我們定義了狗進程和貓進程，但是如果你有多個狗進程：Fido 和 Spot，而你想要阻止 Fido 去吃 Spot 的狗糧 <code>dog_chow</code> 怎麼辦呢?</p><p><img src="https://opensource.com/sites/default/files/resize/images/life-uploads/mcs-enforcement_02_fido-eat-spot-food-500x251.png" alt="SELinux rule" title="SELinux rule"></p><p>一個解決方式是創建大量的新類型，如 <code>Fido_dog</code> 和 <code>Fido_dog_chow</code>。但是這很快會變得難以駕馭因為所有的狗都有差不多相同的權限。</p><p>為了解決這個問題我們發明了一種新的強制形式，叫做多類別安全（Multi Category Security）（MCS）。在 MCS 中，我們在狗進程和狗糧的標籤上增加了另外一部分標籤。現在我們將狗進程標記為 <code>dog:random1(Fido)</code> 和 <code>dog:random2(Spot)</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_01_fido-spot.png" alt="Cartoon of two dogs fido and spot"></p><p>我們將狗糧標記為 <code>dog_chow:random1(Fido)</code> 和 <code>dog_chow:random2(Spot)</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_03_foods.png" alt="SELinux rule" title="SELinux rule"></p><p>MCS 規則聲明如果類型強制規則被遵守而且該 MCS 隨機標籤正確匹配，則訪問是允許的，否則就會被拒絕。</p><p>Fido (<code>dog:random1</code>) 嘗試去吃 <code>cat_chow:food</code> 被類型強制拒絕了。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_04-bad-fido-cat-chow.png" alt="Cartoon of Kernel (Penquin) holding leash to prevent Fido from eating cat food."></p><p>Fido (<code>dog:random1</code>) 允許去吃 <code>dog_chow:random1</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_05_fido-eat-fido-food.png" alt="Cartoon Fido happily eating his dog food"></p><p>Fido (<code>dog:random1</code>) 去吃 spot(<code>dog_chow:random2</code>)的食物被拒絕。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mcs-enforcement_06_fido-no-spot-food.png" alt="Cartoon of Kernel (Penquin) holding leash to prevent Fido from eating spots dog food."></p><p><em>現實例子</em></p><p>在計算機系統中我們經常有很多具有同樣訪問權限的進程，但是我們又希望它們各自獨立。有時我們稱之為多租户環境（multi-tenant environment）。最好的例子就是虛擬機。如果我有一個運行很多虛擬機的服務器，而其中一個被劫持，我希望能夠阻止它去攻擊其它虛擬機和虛擬機鏡像。但是在一個類型強制系統中 KVM 虛擬機被標記為 <code>svirt_t</code> 而鏡像被標記為 <code>svirt_image_t</code>。 我們允許 <code>svirt_t</code> 可以讀/寫/刪除標記為 <code>svirt_image_t</code> 的上下文。通過使用 libvirt 我們不僅實現了類型強制隔離，而且實現了 MCS 隔離。當 libvirt 將要啓動一個虛擬機時，它會挑選出一個 MCS 隨機標籤如 <code>s0:c1,c2</code>，接着它會將 <code>svirt_image_t:s0:c1,c2</code> 標籤分發給虛擬機需要去操作的所有上下文。最終，虛擬機以 <code>svirt_t:s0:c1,c2</code> 為標籤啓動。因此，SELinux 內核控制 <code>svirt_t:s0:c1,c2</code> 不允許寫向 <code>svirt_image_t:s0:c3,c4</code>，即使虛擬機被一個黑客劫持並接管，即使它是運行在 root 下。</p>',46)),t("p",null,[e[1]||(e[1]=o("我們在 OpenShift 中使用",-1)),s(d,{href:"http://people.fedoraproject.org/~dwalsh/SELinux/Presentations/openshift_selinux.ogv"},{default:i(()=>[...e[0]||(e[0]=[o("類似的隔離策略",-1)])]),_:1}),e[2]||(e[2]=o("。每一個 gear（user/app process）都有相同的 SELinux 類型（",-1)),e[3]||(e[3]=t("code",null,"openshift_t",-1)),e[4]||(e[4]=o("）（LCTT 譯註：gear 為 OpenShift 的計量單位）。策略定義的規則控制着 gear 類型的訪問權限，而一個獨一無二的 MCS 標籤確保了一個 gear 不能影響其他 gear。",-1))]),t("p",null,[e[6]||(e[6]=o("請觀看",-1)),s(d,{href:"http://people.fedoraproject.org/~dwalsh/SELinux/Presentations/openshift_selinux.ogv"},{default:i(()=>[...e[5]||(e[5]=[o("這個短視頻",-1)])]),_:1}),e[7]||(e[7]=o("來看 OpenShift gear 切換到 root 會發生什麼。",-1))]),e[24]||(e[24]=p('<h3 id="多級別安全強制" tabindex="-1">多級別安全強制 <a class="header-anchor" href="#多級別安全強制" aria-label="Permalink to “多級別安全強制”">​</a></h3><p>另外一種不經常使用的 SELinux 強制形式叫做多級別安全（Multi Level Security）（MLS）；它開發於上世紀 60 年代，並且主要使用在受信操作系統上如 Trusted Solaris。</p><p>其核心觀點就是通過進程使用的數據等級來控制進程。一個 <em>secret</em> 進程不能讀取 <em>top secret</em> 數據。</p><p>MLS 很像 MCS，除了它在強制策略中增加了支配的概念。MCS 標籤必須完全匹配，但一個 MLS 標籤可以支配另一個 MLS 標籤並且獲得訪問。</p><p><em>打個比方</em></p><p>不討論不同名字的狗，我們現在來看不同種類。我們現在有一隻格雷伊獵犬和一隻吉娃娃。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mls-enforcement_01_chigrey.png" alt="Cartoon of a Greyhound and a Chihuahua"></p><p>我們可能想要允許格雷伊獵犬去吃任何狗糧，但是吉娃娃如果嘗試去吃格雷伊獵犬的狗糧可能會被嗆到。</p><p>我們把格雷伊獵犬標記為 <code>dog:Greyhound</code>，把它的狗糧標記為 <code>dog_chow:Greyhound</code>，把吉娃娃標記為 <code>dog:Chihuahua</code>，把它的狗糧標記為 <code>dog_chow:Chihuahua</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mls-enforcement_04_mlstypes.png" alt="Cartoon of a Greyhound dog food and a Chihuahua dog food."></p><p>使用 MLS 策略，我們可以使 MLS 格雷伊獵犬標籤支配吉娃娃標籤。這意味着 <code>dog:Greyhound</code> 允許去吃 <code>dog_chow:Greyhound</code> 和 <code>dog_chow:Chihuahua</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mls-enforcement_05_chigreyeating.png" alt="SELinux rule" title="SELinux rule"></p><p>但是 <code>dog:Chihuahua</code> 不允許去吃 <code>dog_chow:Greyhound</code>。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mls-enforcement_03_chichoke.png" alt="Cartoon of Kernel (Penquin) stopping the Chihahua from eating the greyhound food.  Telling him it would be a big too beefy for him."></p><p>當然，由於類型強制， <code>dog:Greyhound</code> 和 <code>dog:Chihuahua</code> 仍然不允許去吃 <code>cat_chow:Siamese</code>，即使 MLS 類型 GreyHound 支配 Siamese。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/mls-enforcement_06_nocatchow.png" alt="Cartoon of Kernel (Penquin) holding leash to prevent both dogs from eating cat food."></p><p><em>現實例子</em></p><p>有兩個 Apache 服務器：一個以 <code>httpd_t:TopSecret</code> 運行，一個以 <code>httpd_t:Secret</code> 運行。如果 Apache 進程 <code>httpd_t:Secret</code> 被劫持，黑客可以讀取 <code>httpd_sys_content_t:Secret</code> 但會被禁止讀取 <code>httpd_sys_content_t:TopSecret</code>。</p><p>但是如果運行 <code>httpd_t:TopSecret</code> 的 Apache 進程被劫持，它可以讀取 <code>httpd_sys_content_t:Secret</code> 數據和 <code>httpd_sys_content_t:TopSecret</code> 數據。</p><p>我們在軍事系統上使用 MLS，一個用户可能被允許讀取 <em>secret</em> 數據，但是另一個用户在同一個系統上可以讀取 <em>top secret</em> 數據。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>SELinux 是一個功能強大的標籤系統，控制着內核授予每個進程的訪問權限。最主要的特性是類型強制，策略規則定義的進程訪問權限基於進程被標記的類型和客體被標記的類型。也引入了另外兩個控制手段，分離有着同樣類型進程的叫做 MCS，而 MLS，則允許進程間存在支配等級。</p>',22)),t("p",null,[t("em",null,[e[9]||(e[9]=o("*所有的漫畫都來自 ",-1)),s(d,{href:"https://opensource.com/users/mairin"},{default:i(()=>[...e[8]||(e[8]=[o("Máirín Duffy",-1)])]),_:1})])]),e[25]||(e[25]=t("hr",null,null,-1)),e[26]||(e[26]=t("p",null,"作者簡介：",-1)),e[27]||(e[27]=t("p",null,"Daniel J Walsh - Daniel Walsh 已經在計算機安全領域工作了將近 30 年。Daniel 與 2001 年 8 月加入紅帽。",-1)),e[28]||(e[28]=t("hr",null,null,-1)),t("p",null,[e[11]||(e[11]=o("via: ",-1)),s(d,{href:"https://opensource.com/business/13/11/selinux-policy-guide"},{default:i(()=>[...e[10]||(e[10]=[o("https://opensource.com/business/13/11/selinux-policy-guide",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=o("作者：",-1)),s(d,{href:"https://opensource.com/users/rhatdan"},{default:i(()=>[...e[12]||(e[12]=[o("Daniel J Walsh",-1)])]),_:1}),e[16]||(e[16]=o(" 譯者：",-1)),s(d,{href:"https://github.com/xiaow6"},{default:i(()=>[...e[13]||(e[13]=[o("xiaow6",-1)])]),_:1}),e[17]||(e[17]=o(" 校對：",-1)),s(d,{href:"https://github.com/wxy"},{default:i(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[20]||(e[20]=o("本文由 ",-1)),s(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原創編譯，",-1)),s(d,{href:"https://linux.cn/"},{default:i(()=>[...e[19]||(e[19]=[o("Linux中國",-1)])]),_:1}),e[22]||(e[22]=o(" 榮譽推出",-1))])])}const L=n(c,[["render",u]]);export{C as __pageData,L as default};
